package net.civeira.phylax.feature.template.templatevariable.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.template.templatevariable.domain.TemplateVariable;
import net.civeira.phylax.feature.template.templatevariable.domain.valueobject.ValueVO;

class ValueValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of value of template variable")
  void test_value_value_holder_assign_plain_value() {
    Object holder = new Object();
    ValueValueHolder<Object> value = new ValueValueHolder<>(holder);
    Assertions.assertSame(holder, value.value("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getValueValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getValue().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.valueNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getValueValue().isPresent(), "A null value object must be stored");
    Assertions.assertFalse(value.getValue().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of value of template variable")
  void test_value_value_holder_assign_value_object() {
    Object holder = new Object();
    ValueValueHolder<Object> value = new ValueValueHolder<>(holder);
    ValueVO vo = ValueVO.from("one");
    Assertions.assertFalse(value.getValueValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.value(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getValueValue().orElseThrow());
    Assertions.assertSame(holder, value.value(Optional.empty()));
    Assertions.assertFalse(value.getValueValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.value(Optional.of(vo)));
    Assertions.assertSame(vo, value.getValueValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of value of template variable against the original")
  void test_value_value_holder_read() {
    Object holder = new Object();
    ValueValueHolder<Object> value = new ValueValueHolder<>(holder);
    ValueVO vo = ValueVO.from("one");
    ValueVO other = ValueVO.from("one");
    TemplateVariable original = Mockito.mock(TemplateVariable.class);
    Mockito.when(original.getValueValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readValue(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readValue(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.value(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readValue(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readValue(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of value of template variable")
  void test_value_value_holder_unset() {
    Object holder = new Object();
    ValueValueHolder<Object> value = new ValueValueHolder<>(holder);
    ValueVO vo = ValueVO.from("one");
    value.value(vo);
    Assertions.assertSame(holder, value.unsetValueIfMatches("value_other"));
    Assertions.assertTrue(value.getValueValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetValueIfMatches("value"));
    Assertions.assertFalse(value.getValueValue().isPresent(),
        "The field name must clear the value");
    value.value(vo);
    Assertions.assertSame(holder, value.unsetValue());
    Assertions.assertFalse(value.getValueValue().isPresent(), "Unset must clear the value");
  }
}
